    static func embolden(_ S: [RShape]) -> [RShape] {
        return S.map { (q: RShape) -> RShape in
            if q.fixed {
                return q
            }
            switch q.k {
            case "disc":
                return RShape.make([q]) { _o in _o.r = q.r * 1.55 }
            case "dots":
                return RShape.make([q]) { _o in _o.r = q.r * 1.5 }
            case "ring":
