                    var x1: Double = -Double.infinity
                    var y0: Double = Double.infinity
                    var y1: Double = -Double.infinity
                    var cx: Double = 0.0
                    var cy: Double = 0.0
                    let n: Double = Double(q.p.count) / 2.0
                    do {
                        var i: Double = 0.0
                        while i < Double(q.p.count) {
                            defer { i += 2.0 }
                            x0 = JS.min(x0, q.p[Int(i)])
                            x1 = JS.max(x1, q.p[Int(i)])
                            y0 = JS.min(y0, q.p[Int(i + 1.0)])
                            y1 = JS.max(y1, q.p[Int(i + 1.0)])
                            cx += q.p[Int(i)] / n
                            cy += q.p[Int(i + 1.0)] / n
                        }
